    root.addView(toolbar);notice=new TextView(this);notice.setTextSize(11);notice.setTextColor(Color.rgb(85,97,144));notice.setPadding(dp(12),dp(6),dp(12),dp(6));notice.setText("Android 호환성 시험판 · 선택 글은 길게 눌러 전달");root.addView(notice);
    pendingBar=new LinearLayout(this);pendingBar.setGravity(Gravity.CENTER_VERTICAL);pendingBar.setBackgroundColor(Color.rgb(237,236,255));pendingBar.addView(button("여기에 넣기",v->insertPending()));pendingBar.addView(button("대상 변경",v->{if(pendingText!=null)destinations(pendingText);}));pendingBar.addView(button("취소",v->clearPending()));pendingBar.setVisibility(View.GONE);root.addView(pendingBar);
